package run.ikaros.finance; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/finance/accounts/{accountId}/actions") public class AccountLifecycleController{private final AccountLifecycleService service;public AccountLifecycleController(AccountLifecycleService s){service=s;}@PostMapping("/archive")public Mono<AccountView> archive(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID accountId){return service.setArchived(a,accountId,true);}@PostMapping("/restore")public Mono<AccountView> restore(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID accountId){return service.setArchived(a,accountId,false);}}
